param([string]$SqlFile,[string]$OutputFile)
$c=New-Object System.Data.SqlClient.SqlConnection 'Server=lpc:.;Database=AdventureWorks2025;Integrated Security=True;TrustServerCertificate=True'
try { $q=$c.CreateCommand(); $q.CommandTimeout=90; $q.CommandText=Get-Content -LiteralPath $SqlFile -Raw; $a=New-Object System.Data.SqlClient.SqlDataAdapter $q; $ds=New-Object System.Data.DataSet; [void]$a.Fill($ds); $results=@(); foreach($t in $ds.Tables){$rows=@(); foreach($row in $t.Rows){$o=[ordered]@{}; foreach($col in $t.Columns){$v=$row[$col.ColumnName]; if($v -is [DBNull]){$v=$null}; $o[$col.ColumnName]=$v}; $rows += [pscustomobject]$o}; $results += ,$rows}; $json=ConvertTo-Json -InputObject $results -Depth 8; if($OutputFile){Set-Content -LiteralPath $OutputFile -Value $json -Encoding UTF8}; Write-Output $json } finally {$c.Close()}
